#!/usr/bin/env bash
# verify.sh — generated by rhol-verify-feature skill
# Feature: LOG-9994 — Support multiple Elasticsearch endpoints in ClusterLogForwarder
# PR: openshift/cluster-logging-operator#3451
#
# Usage: [KUBECONFIG=...] bash verify.sh
#   Reads KUBECONFIG from the environment / current oc context (never hardcoded).
#   The feature is operator-side (stock Vector collector) — no image override needed.
set -euo pipefail

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
FEATURE_ID="${FEATURE_ID:-LOG-9994}"
NS="${NS:-openshift-logging}"
TEST_NS="${TEST_NS:-test-log-gen}"
CLF_URL_EP="test-url-and-endpoints"   # CLF: url + endpoints (AC5 url-prepended)
CLF_EP_ONLY="test-endpoints-only"     # CLF: endpoints only
ES1="test-es-1"
ES2="test-es-2"

# Unique per-run marker — log generator emits it; delivery checks query it exactly.
NONCE=$(date +%s%N | sha256sum | head -c8)
MARKER="verify-${FEATURE_ID}-${NONCE}"

PASS=0; FAIL=0; TOTAL=0
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"
mkdir -p evidence

echo "=== Run marker: ${MARKER} ==="

# ---------------------------------------------------------------------------
# check() — records PASS/FAIL, must return 0 even on failure (set -e safety)
# ---------------------------------------------------------------------------
check() {
  local desc="$1"; shift
  TOTAL=$((TOTAL + 1))
  local log_file="evidence/check-${TOTAL}.log"
  echo "--- Check $TOTAL: $desc ---" | tee "$log_file"
  if eval "$@" 2>&1 | tee -a "$log_file"; then
    echo "RESULT: PASS" | tee -a "$log_file"
    PASS=$((PASS + 1))
  else
    echo "RESULT: FAIL" | tee -a "$log_file"
    FAIL=$((FAIL + 1))
    return 0
  fi
}

# ---------------------------------------------------------------------------
# Admission helpers (dry-run=server runs apiserver CEL without persisting)
# ---------------------------------------------------------------------------
adm_reject() { # file expected_msg
  local f="$1" msg="$2" out
  out=$(oc apply --dry-run=server -f "$f" 2>&1) && { echo "UNEXPECTED ACCEPT:"; echo "$out"; return 1; }
  echo "$out"
  echo "$out" | grep -q "$msg"
}
adm_accept() { # file
  oc apply --dry-run=server -f "$1" 2>&1
}

# es_count POD MARKER -> prints integer count of docs whose message matches MARKER
es_count() {
  local pod="$1" marker="$2"
  oc exec -n "$NS" "$pod" -- curl -s "http://localhost:9200/_refresh" >/dev/null 2>&1 || true
  oc exec -n "$NS" "$pod" -- curl -s "http://localhost:9200/_count" \
    -H 'Content-Type: application/json' \
    -d "{\"query\":{\"match_phrase\":{\"message\":\"${marker}\"}}}" 2>/dev/null \
    | grep -oP '"count"\s*:\s*\K[0-9]+' | head -1
}

wait_rollout_ds() {
  local ds="$1" ns="${2:-$NS}"
  for _ in $(seq 1 30); do
    oc get daemonset "$ds" -n "$ns" &>/dev/null && break
    sleep 5
  done
  oc rollout status daemonset/"$ds" -n "$ns" --timeout=300s
}

# ---------------------------------------------------------------------------
# Teardown — always runs
# ---------------------------------------------------------------------------
CREATED_NS=false
cleanup() {
  echo "=== Teardown ==="
  oc delete clusterlogforwarder -n "$NS" -l "rhol-verify=${FEATURE_ID}" --ignore-not-found --timeout=60s 2>/dev/null || true
  oc delete pod,svc,serviceaccount,configmap,secret,deployment,daemonset \
    -n "$NS" -l "rhol-verify=${FEATURE_ID}" --ignore-not-found --timeout=60s 2>/dev/null || true
  oc delete clusterrolebinding -l "rhol-verify=${FEATURE_ID}" --ignore-not-found --timeout=30s 2>/dev/null || true
  # Revert SCC grant made for the ES receiver SA
  oc adm policy remove-scc-from-user nonroot -z test-es-sa -n "$NS" 2>/dev/null || true
  if [[ "$CREATED_NS" == "true" ]]; then
    oc delete namespace "$TEST_NS" --ignore-not-found --timeout=120s 2>/dev/null || true
  else
    oc delete deployment,pod -n "$TEST_NS" -l "rhol-verify=${FEATURE_ID}" --ignore-not-found --timeout=60s 2>/dev/null || true
  fi
}
trap cleanup EXIT

# ===========================================================================
# SETUP (runs under set -e — a setup failure aborts; blocked checks are INCONCLUSIVE)
# ===========================================================================

# RBAC: collector SA + collect-application-logs CRB + ES receiver SA
oc apply -f resources/rbac/sa-and-bindings.yaml

# SCC: ES image runs as UID 2000 -> grant nonroot to the dedicated receiver SA
oc adm policy add-scc-to-user nonroot -z test-es-sa -n "$NS"

# Receivers: two independent Elasticsearch nodes
oc apply -f resources/receivers/elasticsearch-multi.yaml
echo "Waiting for Elasticsearch receivers to be Ready..."
oc wait --for=condition=Ready "pod/${ES1}" -n "$NS" --timeout=240s
oc wait --for=condition=Ready "pod/${ES2}" -n "$NS" --timeout=240s

# Log generator (rendered from template with the per-run marker)
if ! oc get namespace "$TEST_NS" &>/dev/null; then
  oc create namespace "$TEST_NS"
  CREATED_NS=true
fi
# Limit substitution to MARKER/TEST_NS so the generator's shell loop vars ($i) survive
MARKER="$MARKER" TEST_NS="$TEST_NS" envsubst '${MARKER} ${TEST_NS}' < resources/log-generator.yaml | oc apply -f -
oc rollout status deployment/log-generator -n "$TEST_NS" --timeout=120s

# CLFs (real resources so the operator generates Vector config + forwards logs)
oc apply -f resources/clf/clf-url-and-endpoints.yaml
oc apply -f resources/clf/clf-endpoints-only.yaml
wait_rollout_ds "$CLF_URL_EP"
wait_rollout_ds "$CLF_EP_ONLY"

# Capture applied specs + generated configs as evidence
oc get clf "$CLF_URL_EP"  -n "$NS" -o yaml > "evidence/${CLF_URL_EP}-clf.yaml"
oc get clf "$CLF_EP_ONLY" -n "$NS" -o yaml > "evidence/${CLF_EP_ONLY}-clf.yaml"
oc get configmap "${CLF_URL_EP}-config"  -n "$NS" -o yaml > "evidence/${CLF_URL_EP}-config.yaml"  2>/dev/null || true
oc get configmap "${CLF_EP_ONLY}-config" -n "$NS" -o yaml > "evidence/${CLF_EP_ONLY}-config.yaml" 2>/dev/null || true

# ===========================================================================
# CHECKS (acceptance-criteria verification)
# ===========================================================================

# AC1 — Elasticsearch struct has new optional `endpoints` field (CRD schema)
check "AC1: CRD elasticsearch output has 'endpoints' array property with per-item isURL CEL" \
  "oc get crd clusterlogforwarders.observability.openshift.io -o json \
    | python3 -I -c 'import sys,json; d=json.load(sys.stdin); v=[x for x in d[\"spec\"][\"versions\"] if x[\"name\"]==\"v1\"][0]; es=v[\"schema\"][\"openAPIV3Schema\"][\"properties\"][\"spec\"][\"properties\"][\"outputs\"][\"items\"][\"properties\"][\"elasticsearch\"]; props=es[\"properties\"]; assert \"endpoints\" in props, \"no endpoints\"; assert props[\"endpoints\"][\"items\"][\"x-kubernetes-validations\"][0][\"rule\"]==\"isURL(self)\"; print(\"endpoints present; item rule=isURL(self)\")'"

# AC2 — url is optional (not in required)
check "AC2: CRD elasticsearch 'required' does not include 'url' (url optional)" \
  "oc get crd clusterlogforwarders.observability.openshift.io -o json \
    | python3 -I -c 'import sys,json; d=json.load(sys.stdin); v=[x for x in d[\"spec\"][\"versions\"] if x[\"name\"]==\"v1\"][0]; es=v[\"schema\"][\"openAPIV3Schema\"][\"properties\"][\"spec\"][\"properties\"][\"outputs\"][\"items\"][\"properties\"][\"elasticsearch\"]; req=es.get(\"required\",[]); assert \"url\" not in req, req; print(\"required=\",req)'"

# AC3 — CEL: at least one of url/endpoints required (negative: neither -> rejected)
check "AC3-neg: CLF with neither url nor endpoints is REJECTED ('URL or endpoints required')" \
  "adm_reject resources/admission/neither-url-nor-endpoints.yaml 'URL or endpoints required'"

# AC3 — positive: endpoints-only is accepted
check "AC3-pos: CLF with endpoints-only is ACCEPTED by admission" \
  "adm_accept resources/admission/endpoints-only.yaml >/dev/null && echo 'endpoints-only accepted'"

# AC4 — CEL: endpoints entries must be valid URLs (negative)
check "AC4: endpoints entry that is not a URL is REJECTED ('invalid URL')" \
  "adm_reject resources/admission/invalid-endpoint-url.yaml 'invalid URL'"

# AC7 — mixed http/https schemes accepted
check "AC7: mixed http/https endpoints are ACCEPTED by admission" \
  "adm_accept resources/admission/mixed-scheme.yaml >/dev/null && echo 'mixed-scheme accepted'"

# AC9 — backward compat: url-only manifest still accepted
check "AC9: existing url-only manifest is ACCEPTED unchanged" \
  "adm_accept resources/admission/url-only.yaml >/dev/null && echo 'url-only accepted'"

# AC5 — generated Vector config prepends url to endpoints (url+endpoints CLF)
check "AC5: generated config for '${CLF_URL_EP}' has endpoints=[test-es-1, test-es-2] (url first)" \
  "grep -h 'endpoints' evidence/${CLF_URL_EP}-config.yaml | grep -E 'test-es-1.*test-es-2'"

# AC5/endpoints — generated config for endpoints-only contains both endpoints
check "AC5b: generated config for '${CLF_EP_ONLY}' endpoints list contains test-es-1 AND test-es-2" \
  "grep -h 'endpoints' evidence/${CLF_EP_ONLY}-config.yaml | grep -E 'test-es-1.*test-es-2'"

# E2E delivery — marker reaches the Elasticsearch endpoint cluster
echo "Allowing ~60s for logs to flow to the Elasticsearch endpoints..."
sleep 60
check "E2E: marker '${MARKER}' delivered to the multi-endpoint ES cluster (es-1 + es-2 >= 1)" \
  'C1=$(es_count '"$ES1"' '"$MARKER"'); C2=$(es_count '"$ES2"' '"$MARKER"'); C1=${C1:-0}; C2=${C2:-0}; echo "test-es-1 count=$C1 test-es-2 count=$C2 total=$((C1+C2))"; [ $((C1+C2)) -ge 1 ]'

# ===========================================================================
# SUMMARY
# ===========================================================================
echo ""
echo "=============================="
echo "SUMMARY ${PASS}/${TOTAL} checks passed  (marker ${MARKER})"
if [[ "$FAIL" -gt 0 ]]; then
  echo "FAIL: ${FAIL} check(s) did not pass — see evidence/ for details"
fi
echo "=============================="
exit "$FAIL"
